import re


def parse_notes(notes_str):
    result = {
        'items': None,
        'adj_pct': 0.0,
        'fee': 0.0,
        'waive': False
    }
    if notes_str is None or str(notes_str).strip() == '':
        return result
    notes_str = str(notes_str).strip()

    # Parse items from items=<int>
    m = re.search(r'items=(\d+)', notes_str, flags=re.IGNORECASE)
    if m:
        try:
            result['items'] = int(m.group(1))
        except ValueError:
            result['items'] = None
    else:
        result['items'] = None

    # Parse adj_pct from adj=<signed number>%
    m = re.search(r'adj=([+-]?\d+(?:\.\d+)?)%', notes_str, flags=re.IGNORECASE)
    if m:
        try:
            result['adj_pct'] = float(m.group(1)) / 100.0  # as fraction
        except ValueError:
            result['adj_pct'] = 0.0
    else:
        result['adj_pct'] = 0.0

    # Parse fee from fee=<signed number>
    m = re.search(r'fee=([+-]?\d+(?:\.\d+)?)', notes_str, flags=re.IGNORECASE)
    if m:
        try:
            result['fee'] = float(m.group(1))
        except ValueError:
            result['fee'] = 0.0
    else:
        result['fee'] = 0.0

    # Parse waive from waive=true
    m = re.search(r'waive=(true|false)', notes_str, flags=re.IGNORECASE)
    if m:
        val = m.group(1).lower()
        result['waive'] = (val == 'true')
    else:
        result['waive'] = False

    return result

