import re


def parse_amount_str(s):
    if s is None:
        return float('nan')
    s = str(s).strip()
    if s == '':
        return float('nan')
    original = s

    # Check if negative
    is_negative = False
    if 'CR' in s.upper():
        is_negative = True
    # Remove CR token for processing
    s = re.sub(r'CR', '', s, flags=re.IGNORECASE)
    if s.startswith('(') and s.endswith(')'):
        is_negative = True
        s = s[1:-1]
    if '-' in s:
        is_negative = True
        s = s.replace('-', '')
    if '+' in s:
        s = s.replace('+', '')

    # Remove tokens C1 and C2 - remove as substrings regardless of boundaries
    s = re.sub(r'C1', '', s, flags=re.IGNORECASE)
    s = re.sub(r'C2', '', s, flags=re.IGNORECASE)
    # Remove all letters
    s = re.sub(r'[A-Za-z]', '', s)
    # Remove spaces
    s = re.sub(r'\s+', '', s)

    # Keep only digits, comma, dot
    s = re.sub(r'[^0-9,\.]', '', s)

    if s == '':
        return float('nan')

    # Determine decimal separator using last-separator rule
    comma_count = s.count(',')
    dot_count = s.count('.')

    if comma_count > 0 and dot_count > 0:
        last_comma = s.rfind(',')
        last_dot = s.rfind('.')
        if last_comma > last_dot:
            s = s.replace('.', '')
            s = s.replace(',', '.')
        else:
            s = s.replace(',', '')
    elif comma_count > 0 and dot_count == 0:
        last_comma = s.rfind(',')
        after_comma = s[last_comma + 1:] if last_comma >= 0 else ''
        if len(after_comma) == 2:
            s = s.replace(',', '.')
        else:
            s = s.replace(',', '')
    elif dot_count > 0 and comma_count == 0:
        last_dot = s.rfind('.')
        after_dot = s[last_dot + 1:] if last_dot >= 0 else ''
        if len(after_dot) == 2:
            pass  # keep as decimal
        else:
            # Not exactly 2 digits after - treat as thousand separator, remove
            s = s.replace('.', '')
    else:
        pass

    try:
        result = float(s)
    except Exception:
        return float('nan')

    if is_negative:
        result = -result
    return result

