def parse_event_time(s):
    if s is None:
        return None
    s = str(s).strip()
    if s == '':
        return None
    try:
        # Handle Z suffix
        if s.endswith('Z'):
            # Parse as UTC, return naive equivalent for comparison
            dt = datetime.fromisoformat(s.replace('Z', '+00:00'))
            # Convert to naive by removing tzinfo for simple comparison
            return dt.replace(tzinfo=None)
        # Try direct parse
        try:
            dt = datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                return dt.replace(tzinfo=None)
            return dt
        except:
            pass
        # Try common formats
        for fmt in ['%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S', '%Y-%m-%d']:
            try:
                return datetime.strptime(s, fmt)
            except:
                continue
